/bin/bash -lc "python - <<'PY'
from bioblend.galaxy import GalaxyInstance
import inspect, os
with open(os.environ['GALAXY_API_KEY_FILE']) as fh: key=fh.read().strip()
gi=GalaxyInstance(url='https://usegalaxy.org', key=key)
for n in dir(gi.histories):
    if 'copy' in n or 'create' in n or 'clone' in n or 'import' in n:
        o=getattr(gi.histories,n)
        if callable(o): print(n, inspect.signature(o))
PY"

/bin/bash -lc "python - <<'PY'
from bioblend.galaxy import GalaxyInstance
import inspect, os
with open(os.environ['GALAXY_API_KEY_FILE']) as fh: key=fh.read().strip()
gi=GalaxyInstance(url='https://usegalaxy.org', key=key)
for n in dir(gi.histories):
    if 'copy' in n or 'create' in n or 'clone' in n or 'import' in n:
        o=getattr(gi.histories,n)
        if callable(o): print(n, inspect.signature(o))
PY"

